/**
 * Each sponsor's own mark, traced from their public site (arkiv.network/icon.svg,
 * docs.ens.domains/img/icon.svg, world.org/favicon/safari-pinned-tab.svg) and
 * recolored to currentColor so it sits in our monochrome design in either theme.
 * Attribution, not endorsement: a "built with" credit, the way any hackathon
 * project credits its sponsors.
 */

export function ArkivMark({ className = "h-5 w-5" }: { className?: string }) {
  return (
    <svg viewBox="0 0 64 64" fill="none" className={className} aria-label="Arkiv" role="img">
      <g transform="translate(5 16)" fill="currentColor">
        <path d="M47.1367 0H53.9847V30.24H47.1367V25.664H49.4407V4.576H47.1367V0Z" />
        <path d="M37.1357 25.1202H31.9837L30.4157 20.2882H23.3117L21.7117 25.1202H16.8477V23.3282L24.2717 2.72021H29.6797L37.1357 23.3282V25.1202ZM28.8797 15.6802L26.8957 9.56822L24.8477 15.6802H28.8797Z" />
        <path d="M6.848 30.24H0V0H6.848V4.576H4.544V25.664H6.848V30.24Z" />
      </g>
    </svg>
  )
}

