export function WorldMark({ className = "h-5 w-5" }: { className?: string }) {
  return (
    <svg viewBox="0 0 528 528" className={className} aria-label="World" role="img">
      <g transform="translate(0,528) scale(0.1,-0.1)" fill="currentColor" stroke="none">
        <path d={WORLD_PATH} />
      </g>
    </svg>
  )
}

export function SponsorMark({ id, className }: { id: "arkiv" | "ens" | "world"; className?: string }) {
  if (id === "arkiv") return <ArkivMark className={className} />
  if (id === "ens") return <EnsMark className={className} />
  return <WorldMark className={className} />
}

/** A plain "built with" row, the way any hackathon project credits its sponsors. */
export function BuiltWith({ className = "" }: { className?: string }) {
  const items = [
    { id: "world" as const, name: "World ID" },
    { id: "arkiv" as const, name: "Arkiv" },
    { id: "ens" as const, name: "ENSv2" },
  ]
  return (
    <div className={`flex flex-wrap items-center gap-x-6 gap-y-2 ${className}`}>
      {items.map(({ id, name }) => (
        <span key={id} className="inline-flex items-center gap-2 font-mono text-xs text-foreground/60">
          <SponsorMark id={id} className="h-4 w-4" />
          {name}
        </span>
      ))}
    </div>
  )
}
